import{_ as s,o as n,c as e,U as l}from"./chunks/framework.e625a6bf.js";const g=JSON.parse('{"title":"程序员最常用的10个AI提示词","description":"","frontmatter":{"title":"程序员最常用的10个AI提示词","date":"2026/06/03 18:47:24","summary":"前言 2026年，AI编程已经像Git一样成为标配。 但很多人发现：同一个需求，别人问AI几分钟搞定，自己问AI却要反复改好几轮。 区别不在模型，而在提示词。 好的提示词不是“请写代码”，而是带约束、","config":{"show":true,"top":false,"dir":true,"dirTag":["h3","h4","h5"],"tag":["info","ai"],"valine":true,"valineId":null},"password":false,"outline":[3,5]},"headers":[],"relativePath":"views/blog/ai/2026-0603-程序员最常用的10个AI提示词.md","filePath":"views/blog/ai/2026-0603-程序员最常用的10个AI提示词.md"}'),p={name:"views/blog/ai/2026-0603-程序员最常用的10个AI提示词.md"};function o(t,a,r,c,i,b){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h6 id="原文-掘金" tabindex="-1">原文 <a href="https://juejin.cn/post/7633725015481729030" target="_blank" rel="noreferrer">掘金</a> <a class="header-anchor" href="#原文-掘金" aria-label="Permalink to &quot;原文 [掘金](https://juejin.cn/post/7633725015481729030)&quot;">​</a></h6><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>2026年，AI编程已经像Git一样成为标配。</p><p>但很多人发现：同一个需求，别人问AI几分钟搞定，自己问AI却要反复改好几轮。</p><p>区别不在模型，而在<strong>提示词</strong>。</p><p>好的提示词不是“请写代码”，而是<strong>带约束、给示例、明确输出格式</strong>。</p><p>今天，我从日常高频场景中提炼了10个最实用的提示词模板，希望对你会有所帮助。</p><p>更多项目实战在Java突击队网：susan.net.cn</p><h2 id="一、为什么你的提示词总-差点意思" tabindex="-1">一、为什么你的提示词总“差点意思”？ <a class="header-anchor" href="#一、为什么你的提示词总-差点意思" aria-label="Permalink to &quot;一、为什么你的提示词总“差点意思”？&quot;">​</a></h2><p>很多小伙伴习惯这样问：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">写一个计算订单金额的Java方法</span></span></code></pre></div><p>AI会给你一段代码，但大概率不符合你的项目规范：没用BigDecimal、异常处理缺失、参数校验没有……本质上，AI不知道你的代码风格和边界条件。</p><p>优秀的提示词遵循<strong>STAR原则</strong>：</p><ul><li><strong>S</strong>ituation——背景：我在做什么项目</li><li><strong>T</strong>ask——任务：具体要干什么</li><li><strong>A</strong>ction——约束：用什么技术、遵循什么规范</li><li><strong>R</strong>esult——输出格式：要代码or解释？加注释or不加？</li></ul><p>下面这10个模板，涵盖了需求分析、代码生成、重构、测试、文档、调优、排错等全流程。</p><h2 id="二、10个常用提示词" tabindex="-1">二、10个常用提示词 <a class="header-anchor" href="#二、10个常用提示词" aria-label="Permalink to &quot;二、10个常用提示词&quot;">​</a></h2><h3 id="_1-需求澄清-把模糊需求变成落地文档" tabindex="-1">1. 需求澄清：把模糊需求变成落地文档 <a class="header-anchor" href="#_1-需求澄清-把模糊需求变成落地文档" aria-label="Permalink to &quot;1. 需求澄清：把模糊需求变成落地文档&quot;">​</a></h3><p><strong>适用场景</strong>：产品给你一句话，你需要转成详细设计。直接让AI帮你拆解。</p><p><strong>提示词模板</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">作为后端架构师，请帮我分析这个需求，输出一份技术方案大纲：</span></span>
<span class="line"><span style="color:#babed8;">{需求原文}</span></span>
<span class="line"><span style="color:#babed8;">要求：</span></span>
<span class="line"><span style="color:#babed8;">1. 拆解成用户故事</span></span>
<span class="line"><span style="color:#babed8;">2. 列出涉及的实体和关系</span></span>
<span class="line"><span style="color:#babed8;">3. 给出API端点设计（RESTful风格）</span></span>
<span class="line"><span style="color:#babed8;">4. 指出潜在的技术风险</span></span></code></pre></div><p><strong>案例</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">需求：用户下单后30分钟未支付，自动取消订单并释放库存。</span></span></code></pre></div><p>AI会生成：用户故事 → 订单实体增加status和expire_time字段 → 延时队列/定时扫表方案 → 并发风险、库存超卖风险的讨论。</p><h3 id="_2-生成单测-覆盖正常-异常-边界" tabindex="-1">2. 生成单测：覆盖正常/异常/边界 <a class="header-anchor" href="#_2-生成单测-覆盖正常-异常-边界" aria-label="Permalink to &quot;2. 生成单测：覆盖正常/异常/边界&quot;">​</a></h3><p><strong>适用场景</strong>：写单元测试又烦又浪费时间，让AI按最佳实践帮你生成。</p><p><strong>提示词模板</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">为以下Java方法生成JUnit 5单元测试：</span></span>
<span class="line"><span style="color:#babed8;">{粘贴方法代码}</span></span>
<span class="line"><span style="color:#babed8;">要求：</span></span>
<span class="line"><span style="color:#babed8;">- 覆盖正常场景、异常场景、边界场景</span></span>
<span class="line"><span style="color:#babed8;">- 使用Mockito模拟依赖</span></span>
<span class="line"><span style="color:#babed8;">- 每个测试方法命名清晰（should_xxx_when_xxx）</span></span>
<span class="line"><span style="color:#babed8;">- 断言使用assertEquals，并输出失败信息</span></span></code></pre></div><p><strong>案例</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">public BigDecimal calculateDiscount(BigDecimal amount, int vipLevel) {</span></span>
<span class="line"><span style="color:#babed8;">    if (amount == null || amount.compareTo(BigDecimal.ZERO) &lt;= 0) {</span></span>
<span class="line"><span style="color:#babed8;">        throw new IllegalArgumentException(&quot;金额必须大于0&quot;);</span></span>
<span class="line"><span style="color:#babed8;">    }</span></span>
<span class="line"><span style="color:#babed8;">    // 业务逻辑...</span></span>
<span class="line"><span style="color:#babed8;">}</span></span></code></pre></div><p>AI生成的测试会包含：amount为null抛异常、amount负数抛异常、vipLevel边界值0和5、正常折扣计算等场景。</p><h3 id="_3-代码解释-快速理解复杂逻辑" tabindex="-1">3. 代码解释：快速理解复杂逻辑 <a class="header-anchor" href="#_3-代码解释-快速理解复杂逻辑" aria-label="Permalink to &quot;3. 代码解释：快速理解复杂逻辑&quot;">​</a></h3><p><strong>适用场景</strong>：接手老代码，或看开源项目某个方法看不太懂。</p><p><strong>提示词模板</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">解释下面这段代码的核心逻辑和设计意图：</span></span>
<span class="line"><span style="color:#babed8;">{代码片段}</span></span>
<span class="line"><span style="color:#babed8;">请用通俗语言说明：</span></span>
<span class="line"><span style="color:#babed8;">1. 输入输出是什么</span></span>
<span class="line"><span style="color:#babed8;">2. 关键步骤（用编号列出）</span></span>
<span class="line"><span style="color:#babed8;">3. 使用了什么设计模式（若有）</span></span>
<span class="line"><span style="color:#babed8;">4. 可能的坑或改进点</span></span></code></pre></div><h3 id="_4-重构建议-提升代码质量" tabindex="-1">4. 重构建议：提升代码质量 <a class="header-anchor" href="#_4-重构建议-提升代码质量" aria-label="Permalink to &quot;4. 重构建议：提升代码质量&quot;">​</a></h3><p><strong>适用场景</strong>：一段“祖传代码”看着难受，又不敢乱动。</p><p><strong>提示词模板</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">请作为资深Java架构师，审查以下代码并给出重构建议：</span></span>
<span class="line"><span style="color:#babed8;">{代码片段}</span></span>
<span class="line"><span style="color:#babed8;">重点关注：</span></span>
<span class="line"><span style="color:#babed8;">- 违反SOLID原则的地方</span></span>
<span class="line"><span style="color:#babed8;">- 重复代码</span></span>
<span class="line"><span style="color:#babed8;">- 可读性问题</span></span>
<span class="line"><span style="color:#babed8;">- 性能瓶颈</span></span>
<span class="line"><span style="color:#babed8;">请提供逐条建议，并给出重构后的代码示例。</span></span></code></pre></div><p><strong>案例</strong>：AI识别出过长方法（超过100行）、多个if-else嵌套、重复的日志处理，建议提取方法、使用策略模式或守卫子句。</p><h3 id="_5-异常排查-根据堆栈定位问题" tabindex="-1">5. 异常排查：根据堆栈定位问题 <a class="header-anchor" href="#_5-异常排查-根据堆栈定位问题" aria-label="Permalink to &quot;5. 异常排查：根据堆栈定位问题&quot;">​</a></h3><p><strong>适用场景</strong>：线上报错，日志一堆，不知道哪里下手。</p><p><strong>提示词模板</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">以下是应用抛出的异常堆栈，请分析可能的原因并给出排查思路：</span></span>
<span class="line"><span style="color:#babed8;">{粘贴堆栈}</span></span>
<span class="line"><span style="color:#babed8;">已知：{补充业务上下文}</span></span>
<span class="line"><span style="color:#babed8;">请输出：</span></span>
<span class="line"><span style="color:#babed8;">- 最可能的根本原因</span></span>
<span class="line"><span style="color:#babed8;">- 需要检查哪几个类（文件名+行号）</span></span>
<span class="line"><span style="color:#babed8;">- 建议的临时修复和长期方案</span></span></code></pre></div><p><strong>案例</strong>：<code>NullPointerException</code> 发生在 <code>OrderService.line58</code>，AI根据上下文推断可能是user为null，建议检查user的获取逻辑或增加防御性判空。</p><h3 id="_6-性能优化-分析慢接口" tabindex="-1">6. 性能优化：分析慢接口 <a class="header-anchor" href="#_6-性能优化-分析慢接口" aria-label="Permalink to &quot;6. 性能优化：分析慢接口&quot;">​</a></h3><p><strong>适用场景</strong>：某个接口响应慢，你怀疑SQL或算法有问题，让AI帮你扫描代码。</p><p><strong>提示词模板</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">以下是一个Spring Boot接口的实现，请帮我分析性能瓶颈：</span></span>
<span class="line"><span style="color:#babed8;">{代码}</span></span>
<span class="line"><span style="color:#babed8;">请特别关注：</span></span>
<span class="line"><span style="color:#babed8;">- 循环内的数据库查询（N+1）</span></span>
<span class="line"><span style="color:#babed8;">- 可并行化的地方</span></span>
<span class="line"><span style="color:#babed8;">- 缓存使用机会</span></span>
<span class="line"><span style="color:#babed8;">- 大对象/集合的创建</span></span>
<span class="line"><span style="color:#babed8;">输出优化建议和示例代码。</span></span></code></pre></div><p><strong>案例</strong>：AI发现在for循环里调用了订单详情查询，建议改成批量查询或使用JOIN一次性取出。</p><h3 id="_7-生成sql与索引建议" tabindex="-1">7. 生成SQL与索引建议 <a class="header-anchor" href="#_7-生成sql与索引建议" aria-label="Permalink to &quot;7. 生成SQL与索引建议&quot;">​</a></h3><p><strong>适用场景</strong>：设计表结构或优化慢SQL。</p><p><strong>提示词模板</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">需求：{描述查询需求}</span></span>
<span class="line"><span style="color:#babed8;">表结构：</span></span>
<span class="line"><span style="color:#babed8;">{CREATE TABLE语句}</span></span>
<span class="line"><span style="color:#babed8;">请：</span></span>
<span class="line"><span style="color:#babed8;">1. 写出符合需求的SQL</span></span>
<span class="line"><span style="color:#babed8;">2. 解释执行计划是否用到了索引</span></span>
<span class="line"><span style="color:#babed8;">3. 推荐创建哪些索引（B-tree/Hash/复合）</span></span>
<span class="line"><span style="color:#babed8;">4. 给出分页优化建议（若需要）</span></span></code></pre></div><p><strong>案例</strong>：AI分析<code>WHERE status = &#39;PAID&#39; AND create_time BETWEEN &#39;2026-01-01&#39; AND &#39;2026-03-31&#39;</code>，建议创建复合索引<code>(status, create_time)</code>，并提醒覆盖索引可避免回表。</p><h3 id="_8-生成结构化知识文档-rag友好" tabindex="-1">8. 生成结构化知识文档（RAG友好） <a class="header-anchor" href="#_8-生成结构化知识文档-rag友好" aria-label="Permalink to &quot;8. 生成结构化知识文档（RAG友好）&quot;">​</a></h3><p><strong>适用场景</strong>：为项目生成Markdown格式的接口文档或问题记录，方便后续被AI检索（RAG）。</p><p><strong>提示词模板</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">根据以下需求/代码，生成一份Markdown格式的技术知识文档：</span></span>
<span class="line"><span style="color:#babed8;">{内容}</span></span>
<span class="line"><span style="color:#babed8;">请包含：</span></span>
<span class="line"><span style="color:#babed8;">- 标题和简短介绍</span></span>
<span class="line"><span style="color:#babed8;">- 关键术语表</span></span>
<span class="line"><span style="color:#babed8;">- 流程图或时序图（Mermaid格式）</span></span>
<span class="line"><span style="color:#babed8;">- 示例请求和响应（若API）</span></span>
<span class="line"><span style="color:#babed8;">- 常见问题与避坑</span></span></code></pre></div><h3 id="_9-设计评审-帮忙找架构设计漏洞" tabindex="-1">9. 设计评审：帮忙找架构设计漏洞 <a class="header-anchor" href="#_9-设计评审-帮忙找架构设计漏洞" aria-label="Permalink to &quot;9. 设计评审：帮忙找架构设计漏洞&quot;">​</a></h3><p><strong>适用场景</strong>：你设计了一个方案，想让AI扮演“技术评审”角色。</p><p><strong>提示词模板</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">你是一位资深的系统架构师。请评审以下设计文档：</span></span>
<span class="line"><span style="color:#babed8;">{文档或描述}</span></span>
<span class="line"><span style="color:#babed8;">从以下角度提出问题：</span></span>
<span class="line"><span style="color:#babed8;">- 可扩展性（未来新增需求会破坏现有设计吗？）</span></span>
<span class="line"><span style="color:#babed8;">- 高可用（单点故障？降级方案？）</span></span>
<span class="line"><span style="color:#babed8;">- 数据一致性（是否有并发写冲突？）</span></span>
<span class="line"><span style="color:#babed8;">- 运维复杂度（部署、监控、扩容）</span></span>
<span class="line"><span style="color:#babed8;">输出：至少3个疑问点和改进建议。</span></span></code></pre></div><h3 id="_10-跨语言翻译-把python代码转成java" tabindex="-1">10. 跨语言翻译：把Python代码转成Java <a class="header-anchor" href="#_10-跨语言翻译-把python代码转成java" aria-label="Permalink to &quot;10. 跨语言翻译：把Python代码转成Java&quot;">​</a></h3><p><strong>适用场景</strong>：找到一份优秀的Python/Go示例，想转成Java。</p><p><strong>提示词模板</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">将以下{语言}代码转换成Java代码：</span></span>
<span class="line"><span style="color:#babed8;">{代码}</span></span>
<span class="line"><span style="color:#babed8;">要求：</span></span>
<span class="line"><span style="color:#babed8;">- 使用Java 17+特性（var、record、switch表达式等）</span></span>
<span class="line"><span style="color:#babed8;">- 保留原逻辑和变量命名风格</span></span>
<span class="line"><span style="color:#babed8;">- 补充必要的异常处理</span></span>
<span class="line"><span style="color:#babed8;">- 输出完整类定义</span></span></code></pre></div><h2 id="三、使用技巧与避坑指南" tabindex="-1">三、使用技巧与避坑指南 <a class="header-anchor" href="#三、使用技巧与避坑指南" aria-label="Permalink to &quot;三、使用技巧与避坑指南&quot;">​</a></h2><ul><li><strong>给示例胜过给描述</strong>：想让AI输出特定格式的JSON，直接给一个例子最有效。</li><li><strong>用分隔符隔离上下文</strong>：例如用“— 我是代码 —”标记代码块，避免跟指令混在一起。</li><li><strong>一次只问一件事</strong>：复合问题分开问，产出的质量和速度更稳。</li><li><strong>开启联网搜索</strong>：最新API、依赖版本更新，建议让AI先检索网络再回答。</li><li><strong>把纠错成本前移</strong>：先让AI列出假设再写代码，可以有效降低幻觉风险。</li></ul><p>更多项目实战在Java突击队网：susan.net.cn/project</p><h2 id="四、总结" tabindex="-1">四、总结 <a class="header-anchor" href="#四、总结" aria-label="Permalink to &quot;四、总结&quot;">​</a></h2><p>在AI编程时代，<strong>“会提问”比“会写代码”更稀缺</strong>。</p><p>这10个提示词覆盖了程序员日常工作的核心场景，建议收藏下来，下次面对具体任务直接套用。</p><p>AI不是魔法，它是你用得越顺手越强的工具。</p><p>把提示词打磨好，你就能把时间花在更有价值的架构设计上，而不是重复的增删改查。</p>`,74)])])}const h=s(p,[["render",o]]);export{g as __pageData,h as default};
